        INCLUDE "msx.inc"
        OUTPUT "ixh.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld ix, $9ABC
        ld hl, $1234
        ld a, ixh               ; DD 7C: LD A,H with the IX prefix
        ld b, ixl               ; DD 45: LD B,L with the IX prefix
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
